-- =============================================================================
-- PLAN B — Initial migration (Milestone 2: Database Foundation)
-- Generated by hand from prisma/schema.prisma, in the shape `prisma migrate
-- dev` produces, to unblock schema validation in a sandbox where the Prisma
-- engine binary cannot be downloaded (see apps/api/README note). Running
-- `pnpm db:migrate` in a normal environment will regenerate/verify this
-- migration against the schema automatically.
-- =============================================================================

-- =========================
-- ENUM TYPES
-- =========================
CREATE TYPE "user_role" AS ENUM ('STUDENT', 'ADMIN', 'CONTENT_OPS', 'CREATOR', 'FACULTY');
CREATE TYPE "user_status" AS ENUM ('ACTIVE', 'CLOSED');
CREATE TYPE "course_status" AS ENUM ('ACTIVE', 'COMING_SOON');
CREATE TYPE "branch_status" AS ENUM ('ACTIVE', 'COMING_SOON');
CREATE TYPE "resource_status" AS ENUM ('DRAFT', 'SCHEDULED', 'LIVE', 'HIDDEN', 'NEED_UPDATE', 'ARCHIVED', 'EXPIRED', 'DELETED');
CREATE TYPE "order_status" AS ENUM ('PENDING', 'PAID', 'FAILED', 'REFUNDED', 'CANCELLED');
CREATE TYPE "payment_status" AS ENUM ('INITIATED', 'VERIFIED', 'FAILED');
CREATE TYPE "coupon_discount_type" AS ENUM ('PERCENTAGE', 'FLAT_AMOUNT');
CREATE TYPE "coupon_status" AS ENUM ('ACTIVE', 'EXPIRED');
CREATE TYPE "review_moderation_status" AS ENUM ('PENDING', 'APPROVED', 'REJECTED');
CREATE TYPE "support_ticket_status" AS ENUM ('OPEN', 'IN_PROGRESS', 'RESOLVED');
CREATE TYPE "announcement_status" AS ENUM ('SCHEDULED', 'ACTIVE', 'EXPIRED');
CREATE TYPE "announcement_audience_scope" AS ENUM ('ALL', 'COURSE', 'BRANCH');
CREATE TYPE "notification_type" AS ENUM ('RECEIPT', 'VERSION_UPDATE', 'ANNOUNCEMENT_DELIVERY', 'SUPPORT_REPLY');
CREATE TYPE "notification_channel" AS ENUM ('EMAIL', 'IN_APP');

-- =========================
-- users
-- =========================
CREATE TABLE "users" (
    "id" UUID NOT NULL,
    "email" TEXT NOT NULL,
    "phone" TEXT,
    "password_hash" TEXT,
    "google_id" TEXT,
    "name" TEXT,
    "avatar_ref" TEXT,
    "role" "user_role" NOT NULL DEFAULT 'STUDENT',
    "status" "user_status" NOT NULL DEFAULT 'ACTIVE',
    "notification_preferences" JSONB,
    "closed_at" TIMESTAMPTZ(6),
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,
    CONSTRAINT "users_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "users_email_key" ON "users"("email");
CREATE UNIQUE INDEX "users_phone_key" ON "users"("phone");
CREATE UNIQUE INDEX "users_google_id_key" ON "users"("google_id");
CREATE INDEX "users_role_idx" ON "users"("role");
CREATE INDEX "users_status_idx" ON "users"("status");

-- =========================
-- universities
-- =========================
CREATE TABLE "universities" (
    "id" UUID NOT NULL,
    "name" TEXT NOT NULL,
    "short_code" TEXT NOT NULL,
    "archived_at" TIMESTAMPTZ(6),
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,
    CONSTRAINT "universities_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "universities_name_key" ON "universities"("name");
CREATE UNIQUE INDEX "universities_short_code_key" ON "universities"("short_code");

-- =========================
-- courses
-- =========================
CREATE TABLE "courses" (
    "id" UUID NOT NULL,
    "university_id" UUID NOT NULL,
    "name" TEXT NOT NULL,
    "slug" TEXT NOT NULL,
    "category" TEXT NOT NULL,
    "status" "course_status" NOT NULL DEFAULT 'COMING_SOON',
    "display_order" INTEGER NOT NULL DEFAULT 0,
    "archived_at" TIMESTAMPTZ(6),
    "created_by_id" UUID NOT NULL,
    "updated_by_id" UUID,
    "deleted_by_id" UUID,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,
    CONSTRAINT "courses_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "courses_slug_key" ON "courses"("slug");
CREATE INDEX "courses_university_id_idx" ON "courses"("university_id");
CREATE INDEX "courses_status_idx" ON "courses"("status");
ALTER TABLE "courses" ADD CONSTRAINT "courses_university_id_fkey" FOREIGN KEY ("university_id") REFERENCES "universities"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "courses" ADD CONSTRAINT "courses_created_by_id_fkey" FOREIGN KEY ("created_by_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "courses" ADD CONSTRAINT "courses_updated_by_id_fkey" FOREIGN KEY ("updated_by_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "courses" ADD CONSTRAINT "courses_deleted_by_id_fkey" FOREIGN KEY ("deleted_by_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;

