CREATE INDEX "branch_semester_subjects_subject_id_idx" ON "branch_semester_subjects"("subject_id");
ALTER TABLE "branch_semester_subjects" ADD CONSTRAINT "branch_semester_subjects_branch_id_fkey" FOREIGN KEY ("branch_id") REFERENCES "branches"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "branch_semester_subjects" ADD CONSTRAINT "branch_semester_subjects_semester_id_fkey" FOREIGN KEY ("semester_id") REFERENCES "semesters"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "branch_semester_subjects" ADD CONSTRAINT "branch_semester_subjects_subject_id_fkey" FOREIGN KEY ("subject_id") REFERENCES "subjects"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "branch_semester_subjects" ADD CONSTRAINT "branch_semester_subjects_created_by_id_fkey" FOREIGN KEY ("created_by_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

