ALTER TABLE "bundles" ADD CONSTRAINT "bundles_deleted_by_id_fkey" FOREIGN KEY ("deleted_by_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- =========================
-- resources
-- (current_version_id FK added AFTER resource_versions exists, below,
--  because Resource <-> ResourceVersion is a circular relationship)
-- =========================
CREATE TABLE "resources" (
    "id" UUID NOT NULL,
    "title" TEXT NOT NULL,
    "slug" TEXT NOT NULL,
    "subject_id" UUID,
    "resource_type_id" UUID NOT NULL,
    "tags" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
    "description" TEXT,
    "page_count" INTEGER,
    "file_size" INTEGER,
    "language" TEXT NOT NULL DEFAULT 'en',
    "meta_title" TEXT,
    "meta_description" TEXT,
    "canonical_branch_id" UUID,
    "preview_unlocked_page_ratio" INTEGER NOT NULL DEFAULT 25,
    "preview_asset_ref" TEXT,
    "thumbnail_ref" TEXT,
    "current_version_id" UUID,
    "status" "resource_status" NOT NULL DEFAULT 'DRAFT',
    "visible_from" TIMESTAMPTZ(6),
    "visible_until" TIMESTAMPTZ(6),
    "price" DECIMAL(10,2) NOT NULL,
    "discount_price" DECIMAL(10,2),
    "owner_id" UUID,
    "search_rank_boost" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "review_average" DECIMAL(3,2) NOT NULL DEFAULT 0,
    "review_count" INTEGER NOT NULL DEFAULT 0,
    "created_by_id" UUID NOT NULL,
    "updated_by_id" UUID,
    "deleted_by_id" UUID,
    "published_at" TIMESTAMPTZ(6),
    "published_by_id" UUID,
    "deleted_at" TIMESTAMPTZ(6),
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,
    CONSTRAINT "resources_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "resources_slug_key" ON "resources"("slug");
CREATE INDEX "resources_status_idx" ON "resources"("status");
CREATE INDEX "resources_subject_id_resource_type_id_idx" ON "resources"("subject_id", "resource_type_id");
CREATE INDEX "resources_resource_type_id_idx" ON "resources"("resource_type_id");
CREATE INDEX "resources_canonical_branch_id_idx" ON "resources"("canonical_branch_id");
CREATE INDEX "resources_owner_id_idx" ON "resources"("owner_id");
CREATE INDEX "resources_title_idx" ON "resources"("title");
ALTER TABLE "resources" ADD CONSTRAINT "resources_subject_id_fkey" FOREIGN KEY ("subject_id") REFERENCES "subjects"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "resources" ADD CONSTRAINT "resources_resource_type_id_fkey" FOREIGN KEY ("resource_type_id") REFERENCES "resource_types"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "resources" ADD CONSTRAINT "resources_canonical_branch_id_fkey" FOREIGN KEY ("canonical_branch_id") REFERENCES "branches"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "resources" ADD CONSTRAINT "resources_owner_id_fkey" FOREIGN KEY ("owner_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "resources" ADD CONSTRAINT "resources_created_by_id_fkey" FOREIGN KEY ("created_by_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "resources" ADD CONSTRAINT "resources_updated_by_id_fkey" FOREIGN KEY ("updated_by_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "resources" ADD CONSTRAINT "resources_deleted_by_id_fkey" FOREIGN KEY ("deleted_by_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "resources" ADD CONSTRAINT "resources_published_by_id_fkey" FOREIGN KEY ("published_by_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- =========================
-- resource_versions
-- =========================
CREATE TABLE "resource_versions" (
    "id" UUID NOT NULL,
    "resource_id" UUID NOT NULL,
    "version_number" INTEGER NOT NULL,
    "file_ref" TEXT NOT NULL,
    "change_notes" TEXT,
    "published_at" TIMESTAMPTZ(6),
    "created_by_id" UUID NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,
    CONSTRAINT "resource_versions_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "resource_versions_resource_id_version_number_key" ON "resource_versions"("resource_id", "version_number");
CREATE INDEX "resource_versions_resource_id_idx" ON "resource_versions"("resource_id");
ALTER TABLE "resource_versions" ADD CONSTRAINT "resource_versions_resource_id_fkey" FOREIGN KEY ("resource_id") REFERENCES "resources"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "resource_versions" ADD CONSTRAINT "resource_versions_created_by_id_fkey" FOREIGN KEY ("created_by_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- Now that resource_versions exists, close the circular relationship:
ALTER TABLE "resources" ADD CONSTRAINT "resources_current_version_id_fkey" FOREIGN KEY ("current_version_id") REFERENCES "resource_versions"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- =========================
